-- M11 §4.3: notification_delivery_attempts only grows. It is the evidence that a user was or was
-- not told, and evidence that can be rewritten is not evidence. Generated by appendOnly() in
-- src/db/helpers/appendOnly.ts — UPDATE and DELETE raise KT001 for everyone including the owner,
-- and komtru_app holds INSERT and SELECT only. No hand-written grants: grantRuntimeAccess() finds
-- the trigger on every later migrate run and keeps the privileges narrow.
--
-- Note what this does to the ON DELETE CASCADE from notifications: the cascaded DELETE hits the
-- trigger, so a notification with attempt history cannot be deleted at all. That is deliberate for
-- now. Whichever ticket introduces a retention policy owns dropping the trigger for its sweep.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "notify"."notification_delivery_attempts" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "notify"."notification_delivery_attempts" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "notify"."notification_delivery_attempts" TO komtru_app;
